for ix,s in enumerate(slides):
 items=s['items'];k=s['kind'];bubble_rows=k=='rows' and ix in (1,8,14,17,26);variant=(' bubble-list' if bubble_rows else '')+(' agent-comparison' if ix==4 else '')+(' stagger-pair' if k=='pair' and ix in (5,9,12,21,25) else '')+(' fan-cards' if k=='columns' else '')+(' open-paper' if k=='code' else '');floating=bubble_rows or k in ('hero','flow','delegate','columns') or (k=='pair' and ix not in (10,16,23));times=s['times'] or [.16+i*.14 for i in range(len(items))]
