 myth=semantics['myths'].get(str(ix),'');myth_markup=f'<div class="deck-myth">{icon("circle-x")}<strong>Mito descartado:</strong><span>{E(myth)}</span></div>' if myth else ''
 html=f'''<!doctype html><html lang="es"><head><meta charset="utf-8"><title>{E(s['title'])}</title></head><body><template><style>{css}\n#{s['id']}{{position:absolute;inset:0;width:100%;height:100%;overflow:hidden}}</style><div id="{s['id']}" data-composition-id="{s['id']}" data-width="1920" data-height="1080" data-duration="{s['duration']}"><section id="frame-{s['id']}" class="deck-frame{variant} clip" data-start="0" data-duration="{s['duration']}" data-track-index="0">{network.replace("network-shade",s["id"]+"-shade").replace("network-mask",s["id"]+"-mask")}<div class="deck-meta"><span>ASmartSolution / Codex</span><span>{E(s['chapter'])}</span></div><div class="deck-rule"></div><h1 class="deck-title">{E(s['title'])}</h1><p class="deck-lead">{E(s['lead'])}</p>{myth_markup}<div class="deck-content{' floating' if floating else ' reading-paper'}">{content}</div><p class="deck-note">{E(s['note'])}</p><div class="deck-pagination">{ix+2:02} / {len(slides)+2}</div></section></div><script>(()=>{{const root=document.getElementById('{s['id']}');const tl=gsap.timeline({{paused:true}});const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;const ambient=gsap.timeline({{paused:true}});const absolute={s['start']+intro_duration};const span={s['duration']};root.querySelectorAll('.network-layer').forEach((el,j)=>{{const pose=t=>({{x:reduced?0:Math.sin((absolute+t)/21+j*2)*26,y:reduced?0:Math.cos((absolute+t)/27+j)*18,rotation:reduced?0:Math.sin((absolute+t)/49+j)*1.2}});const p=pose(0);ambient.fromTo(el,p,{{...pose(span),keyframes:Array.from({{length:Math.max(1,Math.ceil(span))}},(_,i)=>({{...pose((i+1)*span/Math.max(1,Math.ceil(span))),ease:'none'}})),duration:span,ease:'none',immediateRender:false}},0);}});root.querySelectorAll('.light-pulse').forEach(el=>{{const phase=Number(el.dataset.phase);ambient.fromTo(el,{{autoRound:false,strokeDashoffset:-phase-(reduced?0:absolute/28)}},{{autoRound:false,strokeDashoffset:-phase-(reduced?0:(absolute+span)/28),duration:span,ease:'none',immediateRender:false}},0);}});window.__backgroundPainters=window.__backgroundPainters||{{}};window.__backgroundPainters['{s['id']}']=t=>{{if(reduced)return;root.querySelectorAll('.network-layer').forEach((el,j)=>gsap.set(el,{{x:Math.sin(t/21+j*2)*26,y:Math.cos(t/27+j)*18,rotation:Math.sin(t/49+j)*1.2}}));root.querySelectorAll('.light-pulse').forEach(el=>gsap.set(el,{{autoRound:false,strokeDashoffset:-Number(el.dataset.phase)-t/28}}));}};tl.add(ambient,0);ambient.paused(false);window.__ambients=window.__ambients||{{}};window.__ambients['{s['id']}']=ambient;const paper=root.querySelector('.reading-paper');if(paper)tl.fromTo(paper,{{opacity:0,scaleY:reduced?1:.94}},{{opacity:1,scaleY:1,duration:.4,ease:'power3.out',immediateRender:false}},Math.max(0,Number(paper.querySelector('.reveal')?.dataset.cue||0)-.2));tl.fromTo(root.querySelector('.deck-rule'),{{scaleX:0}},{{scaleX:1,duration:.6,ease:'power2.out'}},0);tl.fromTo(root.querySelector('.deck-title'),{{y:reduced?0:16,opacity:0}},{{y:0,opacity:1,duration:.42,ease:'power3.out'}},.05);root.querySelectorAll('.reveal').forEach((el,i)=>{{const at=Number(el.dataset.cue);if(el.tagName.toLowerCase()==='path'){{tl.fromTo(el,{{opacity:0,strokeDashoffset:1}},{{opacity:1,strokeDashoffset:0,duration:.6,ease:'power2.out',immediateRender:false}},at);}}else{{const card=el.matches('.deck-card,.deck-agent,.deck-method,.delegate-agent,.delegate-card'),row=el.matches('.deck-row'),fan=root.classList.contains('fan-cards'),flow=!!el.closest('.deck-flow'),hero=!!el.closest('.deck-hero');const n=[...el.parentElement.children].indexOf(el);const x=fan?(1-n)*260:hero?(n===0?-110:110):row?24:flow?-75:(n%2?90:-90);const y=fan?65:hero?30:card?48:row?0:12;const angle=fan?(n-1)*7:hero?(n===0?-7:6):card?(n%2?3:-3):0;tl.fromTo(el,{{x:reduced?0:x,y:reduced?0:y,scale:reduced?1:(card?.9:1),rotation:reduced?0:angle,opacity:0}},{{x:0,y:0,scale:1,rotation:0,opacity:1,duration:card?.72:row?.5:.48,ease:'power3.out',immediateRender:false}},at);const body=el.querySelector('p');if(body&&!reduced&&!row)tl.fromTo(body,{{clipPath:'inset(0% 100% 0% 0%)',x:14}},{{clipPath:'inset(0% 0% 0% 0%)',x:0,duration:.55,ease:'power2.out',immediateRender:false}},at+.1);}}}});root.querySelectorAll('.delegate-packet').forEach((dot,i)=>{{if(reduced)return;const at=(i===0?3.6:5.3)+.65,endY=i===0?115:375;gsap.set(dot,{{attr:{{cx:415,cy:234}}}});const points=Array.from({{length:30}},(_,j)=>{{const t=(j+1)/30,u=1-t;return {{attr:{{cx:u*u*u*415+3*u*u*t*575+3*u*t*t*620+t*t*t*780,cy:u*u*u*234+3*u*u*t*234+3*u*t*t*endY+t*t*t*endY}},ease:'none'}};}});tl.fromTo(dot,{{opacity:0}},{{opacity:1,duration:.12,immediateRender:false}},at);tl.to(dot,{{keyframes:points,duration:.75,ease:'power1.inOut'}},at);tl.to(dot,{{opacity:0,duration:.15}},at+.75);}});const cards=root.querySelectorAll('.deck-flow .deck-card');cards.forEach((card,i)=>{{if(i<cards.length-1){{const at=Number(cards[i+1].dataset.cue)+.55;tl.fromTo(card,{{borderColor:'#6d8fc4'}},{{borderColor:'#d7e6ff',duration:.25,repeat:1,yoyo:true,immediateRender:false}},at);}}}});const packet=root.querySelector('.flow-packet');if(packet&&!reduced){{const start=Number(cards[2].dataset.cue)+.6;tl.fromTo(packet,{{x:0,opacity:0}},{{x:64,opacity:1,duration:.5,ease:'power1.inOut',immediateRender:false}},start);tl.to(packet,{{opacity:0,duration:.12}},start+.5);tl.fromTo(packet,{{x:505,opacity:0}},{{x:569,opacity:1,duration:.5,ease:'power1.inOut',immediateRender:false}},start+.7);tl.to(packet,{{opacity:0,duration:.12}},start+1.2);}}window.__timelines['{s['id']}']=tl;}})();</script></template></body></html>'''
